// Transport selection order: --transport flag, then PP_MCP_TRANSPORT env,
// then the first transport declared in the spec (see MCPConfig.Transport).
// The flag surface lets one binary serve stdio locally and streamable HTTP
// when hosted in a container or remote sandbox, matching the Anthropic
// guidance that production agents need a remote option.
//
// http mode requires WEAVIATE_COLLECTIONS_MCP_TOKEN to be set: the registered
// tool set includes destructive operations (collection/tenant delete) that run
// with this process's own Weaviate credentials, so an unauthenticated listener
// would let any network caller reach them. The default bind address is
// loopback-only; --addr must be set explicitly to listen on other interfaces.
const (
	defaultHTTPAddr = "127.0.0.1:7777"
)

// version is the printed MCP server's version, overridable at build time via ldflags.
var version = "2026.8.2"

func main() {
	// Pin the learn-event surface for this process and every walker
	// shell-out child, so usage events record surface=mcp.
	_ = os.Setenv("WEAVIATE_COLLECTIONS_LEARN_SURFACE", "mcp")
	s := server.NewMCPServer(
		"Weaviate Collections",
		version,
		server.WithToolCapabilities(false),
	)

	mcptools.RegisterTools(s)

	transport := flag.String("transport", defaultTransport(), "MCP transport: stdio | http")
	addr := flag.String("addr", defaultHTTPAddr, "bind address for http transport (host:port or :port)")
	flag.Parse()

	switch strings.ToLower(*transport) {
	case "stdio":
		if err := server.ServeStdio(s); err != nil {
			fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
			os.Exit(1)
		}
	case "http":
		token := os.Getenv("WEAVIATE_COLLECTIONS_MCP_TOKEN")
		if token == "" {
			fmt.Fprintln(os.Stderr, "MCP server error: WEAVIATE_COLLECTIONS_MCP_TOKEN must be set to use --transport http.")
			fmt.Fprintln(os.Stderr, "The registered tools include destructive operations (e.g. deleting a collection or tenant) that")
			fmt.Fprintln(os.Stderr, "run with this process's own Weaviate credentials, so the HTTP listener requires a bearer token.")
			fmt.Fprintln(os.Stderr, "Generate one yourself and set it, then send it as: Authorization: Bearer <token>")
			os.Exit(2)
		}
		httpSrv := server.NewStreamableHTTPServer(s)
		handler := requireBearerToken(token, httpSrv)
		if isLoopbackAddr(*addr) {
			fmt.Fprintf(os.Stderr, "weaviate-collections-pp-mcp serving MCP over streamable HTTP at %s (bearer token required)\n", *addr)
			if err := http.ListenAndServe(*addr, handler); err != nil {
				fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
				os.Exit(1)
			}
			return
		}
		// Non-loopback bind: the bearer token would otherwise cross the
		// network in plaintext. Require the operator to supply a TLS
		// cert/key pair; there is no plaintext fallback for this case.
		certFile := os.Getenv("WEAVIATE_COLLECTIONS_MCP_TLS_CERT")
		keyFile := os.Getenv("WEAVIATE_COLLECTIONS_MCP_TLS_KEY")
		if certFile == "" || keyFile == "" {
			fmt.Fprintf(os.Stderr, "MCP server error: --addr %q is not loopback-only.\n", *addr)
			fmt.Fprintln(os.Stderr, "Binding to a non-loopback address without TLS would send the bearer token over the network in")
			fmt.Fprintln(os.Stderr, "plaintext. Either drop --addr to keep the loopback-only default, or set both")
			fmt.Fprintln(os.Stderr, "WEAVIATE_COLLECTIONS_MCP_TLS_CERT and WEAVIATE_COLLECTIONS_MCP_TLS_KEY to a PEM cert/key pair.")
			os.Exit(2)
		}
		fmt.Fprintf(os.Stderr, "weaviate-collections-pp-mcp serving MCP over streamable HTTPS at %s (bearer token required)\n", *addr)
		if err := http.ListenAndServeTLS(*addr, certFile, keyFile, handler); err != nil {
			fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
			os.Exit(1)
		}
	default:
		fmt.Fprintf(os.Stderr, "unknown --transport %q (supported: stdio, http)\n", *transport)
		os.Exit(2)
	}
}

// requireBearerToken wraps next so every request must present
// "Authorization: Bearer <token>" matching the configured token before
// reaching the MCP handler. Uses constant-time comparison to avoid leaking
// the token length/prefix through response-timing side channels.
func requireBearerToken(token string, next http.Handler) http.Handler {
	want := "Bearer " + token
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		got := r.Header.Get("Authorization")
		if len(got) != len(want) || subtle.ConstantTimeCompare([]byte(got), []byte(want)) != 1 {
			w.Header().Set("WWW-Authenticate", "Bearer")
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		next.ServeHTTP(w, r)
	})
}

// isLoopbackAddr reports whether addr (a "host:port" listen address) only
// accepts connections from the local machine. An empty host (":7777") binds
// every interface and is NOT loopback; "localhost", "127.0.0.1", and "::1"
// are. Used to decide whether the HTTP transport may skip TLS: plaintext on
// loopback exposes nothing beyond what already trusts this process (e.g. env
// vars), while plaintext on any other address would send the bearer token
// over the network.
func isLoopbackAddr(addr string) bool {
	host, _, err := net.SplitHostPort(addr)
	if err != nil {
		// Not a valid host:port pair; treat conservatively as non-loopback
		// so callers fail closed (require TLS) rather than fail open.
		return false
	}
	switch host {
	case "localhost", "127.0.0.1", "::1":
		return true
	}
	if ip := net.ParseIP(host); ip != nil {
		return ip.IsLoopback()
	}
	return false
}

// defaultTransport reads PP_MCP_TRANSPORT env when set, otherwise falls back
// to "stdio" so running the binary with no args keeps today's behavior.
// Container-hosted agents can pin the transport via env without a flag, which
// matches how hosted-agent process supervisors typically pass configuration.
func defaultTransport() string {
	if t := os.Getenv("PP_MCP_TRANSPORT"); t != "" {
		return t
	}
	return "stdio"
}
